async () => {
  const projectName = 'grok-bot-course';
  const fileHash = "686f7ee70fad1eda9507b2207a2fdfd9";
  const htmlB64 = "";
  const assetBase = 'https://api.cloudflare.com/client/v4/pages/assets';

  const projectRes = await cloudflare.request({
    method: 'GET',
    path: `/accounts/${accountId}/pages/projects/${projectName}`
  });
  const p = projectRes.result || {};

  const tokRes = await cloudflare.request({
    method: 'GET',
    path: `/accounts/${accountId}/pages/projects/${projectName}/upload-token`
  });
  const jwt = tokRes.result && tokRes.result.jwt;
  if (!jwt) {
    return { step: 'upload-token', keys: tokRes.result ? Object.keys(tokRes.result) : null, errors: tokRes.errors };
  }

  const fetchJson = async (path, body, method = 'POST') => {
    const res = await fetch(assetBase + path, {
      method,
      headers: {
        Authorization: 'Bearer ' + jwt,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    });
    const text = await res.text();
    let data;
    try { data = JSON.parse(text); } catch { data = { raw: text.slice(0, 500) }; }
    if (!res.ok) {
      const err = (data && data.errors) ? JSON.stringify(data.errors) : text.slice(0, 500);
      throw new Error(path + ' HTTP ' + res.status + ' ' + err);
    }
    return data;
  };

  let missingHashes = [];
  try {
    const missing = await fetchJson('/check-missing', { hashes: [fileHash] });
    missingHashes = (missing.result && (missing.result.hashes || missing.result)) || missing.hashes || [];
    if (!Array.isArray(missingHashes)) missingHashes = [fileHash];
  } catch (e) {
    return { step: 'check-missing', error: String(e), fetchExists: typeof fetch === 'function' };
  }

  if (missingHashes.includes(fileHash)) {
    try {
      await fetchJson('/upload', [{
        key: fileHash,
        value: htmlB64,
        base64: true,
        metadata: { contentType: 'text/html; charset=utf-8' }
      }]);
    } catch (e) {
      return { step: 'upload', error: String(e), missing: missingHashes };
    }
    try {
      await fetchJson('/upsert-hashes', { hashes: [fileHash] });
    } catch (e) {
      // optional
    }
  }

  const form = new FormData();
  form.append('manifest', JSON.stringify({ 'index.html': fileHash }));
  form.append('branch', 'main');
  form.append('commit_message', 'Grok Bot complete course HTML');

  let deployment;
  try {
    deployment = await cloudflare.request({
      method: 'POST',
      path: `/accounts/${accountId}/pages/projects/${projectName}/deployments`,
      body: form
    });
  } catch (e) {
    return { step: 'deployment', error: String(e), uploaded: missingHashes.includes(fileHash) };
  }

  let domain;
  try {
    domain = await cloudflare.request({
      method: 'POST',
      path: `/accounts/${accountId}/pages/projects/${projectName}/domains`,
      body: { name: 'bot.getcut.cn' }
    });
  } catch (e) {
    domain = { error: String(e) };
  }

  const d = deployment.result || {};
  const dn = domain.result || domain;
  return {
    project: { name: p.name, subdomain: p.subdomain, domains: p.domains },
    uploaded: missingHashes.includes(fileHash),
    deployment: {
      id: d.id,
      url: d.url,
      aliases: d.aliases,
      environment: d.environment,
      latest_stage: d.latest_stage && d.latest_stage.name,
      stage_status: d.latest_stage && d.latest_stage.status,
      created_on: d.created_on
    },
    domain: domain.error ? { error: domain.error } : {
      name: dn.name,
      status: dn.status,
      certificate_authority: dn.certificate_authority,
      validation_data: dn.validation_data,
      verification_data: dn.verification_data
    }
  };
}
